-- Text copied from the live rows, read-only, on 2026-09-27.
begin;
create temp table dt on commit drop as select id from tenants where slug = 'dalatech';
update services s set launch_state = 'live' from dt where s.tenant_id = dt.id;
delete from knowledge_documents k using dt where k.tenant_id = dt.id and k.source = 'D-154';
delete from deterministic_replies d using dt where d.tenant_id = dt.id and d.intent = 'nova_about_live';
delete from reply_cases r using dt where r.tenant_id = dt.id and r.note like 'D-154 founder 2026-09-27: %';
update knowledge_documents k set body = normalize('- Сард 3 богино видео, 8 пост, контент төлөвлөгөө, сурталчилгаа (boost) удирдлага, 7 хоног тутмын тайлан.
- Сурталчилгааны төсөв ороогүй.', NFC), when_service_id = null, when_launch_state = null, updated_at = now()
  from dt where k.tenant_id = dt.id and k.title = normalize('Вира — маркетинг менежер (УДАХГҮЙ, урьдчилан бүртгэл авч байна)', NFC);
update knowledge_documents k set body = normalize('- Нова бол цаг захиалгын сануулгыг SMS-ээр илгээж, ТИЙМ/ҮГҮЙ хариуг хүлээн авдаг AI ажилтан. Одоогоор урьдчилан бүртгэл авч байна.
- Сард 1,000 SMS багтсан.', NFC), when_service_id = null, when_launch_state = null, updated_at = now()
  from dt where k.tenant_id = dt.id and k.title = normalize('Нова — сануулга, SMS (УДАХГҮЙ, урьдчилан бүртгэл авч байна)', NFC);
update knowledge_documents k set body = normalize('- Утсаар хүнтэй адил ярьж, асуултад хариулж, захиалгыг бүртгэнэ.
- Ажлын бус цаг, ачаалалтай үед ч дуудлага алдагдахгүй.
- Үнийг хараахан зарлаагүй.', NFC), when_service_id = null, when_launch_state = null, updated_at = now()
  from dt where k.tenant_id = dt.id and k.title = normalize('Эхо — утасны оператор (УДАХГҮЙ, урьдчилан бүртгэл авч байна)', NFC);
update knowledge_documents k set body = normalize('- Ора зөвхөн тантай ажиллана. Танай харилцагчид ч, багийнхан тань ч түүнтэй харьцахгүй.
- Мессенжер биш, зөвхөн танд нээгддэг чатаар ажиллана.
- Сард 1,500 мессеж багтана. Хэрэглэгч бүр өөрийн 1,500 мессежтэй; нэмэлт хэрэглэгч бүр сар бүр тусдаа төлбөртэй. Нэмэлт 500 мессежийн багц тусдаа төлбөртэй.
- Бичиг баримт унших, боловсруулах: гэрээ, албан бичиг, тайланг уншиж, гол агуулга, анхаарах ёстой зүйлийг нь товч хэлнэ. Шинээр боловсруулахдаа мэргэжлийн албан хэллэгээр найруулна.
- Танилцуулга бэлтгэх: уулзалт, хөрөнгө оруулагч, багийн хурлын танилцуулгыг бүтэц, тоо баримттай нь бэлдэнэ.
- Хугацаа хянах: гэрээний дуусах хугацаа, тайлангийн өдөр, төлбөрийн хуваарийг хөтөлж, хоцрохоос өмнө сануулна.
- Англи хэлнээс хөрвүүлэх: англиар ирсэн гэрээ, захидал, нэхэмжлэхийг утга санааг нь гээхгүйгээр монгол хэл рүү хөрвүүлж, ойлгомжтой тайлбарлана.
- Шийдвэр тунгаах: сонголт бүрийн давуу тал, эрсдэлийг эмхэлж, шийдэхээс өмнө тавих ёстой асуултыг санал болгоно.
- Түүнд өгсөн бичиг баримт, яриа тан дээрээ үлдэнэ. Багийнхан тань ч, танай харилцагчид ч харахгүй.
- Гэрээ бол түүний хийдэг олон ажлын нэг. Хууль зүйн зөвлөгөө өгөхгүй, өмгөөлөгчийг орлохгүй; гэрээний эцсийн шийдвэрийг та өөрөө гаргана.', NFC), when_service_id = null, when_launch_state = null, updated_at = now()
  from dt where k.tenant_id = dt.id and k.title = normalize('Ора — хувийн туслах (УДАХГҮЙ, урьдчилан бүртгэл авч байна)', NFC);
update knowledge_documents k set body = normalize('- Ажилтан бүр сарын тогтмол төлбөртэй, нэг удаагийн суурилуулалттай.
- Дали танай харилцагчидтай Facebook, Instagram, вэбсайтаар монголоор өдөр шөнөгүй ярина.
- Ора харилцагчидтай ярихгүй — зөвхөн тантай ажиллана.
- Вира, Эхо, Нова, Ора хараахан ажиллаж эхлээгүй; урьдчилан бүртгүүлж болно.
- Ажилтнуудыг нэрээр нь дуудна. "Ара" гэдэг нь Далигийн, "Веда" гэдэг нь Вирагийн хуучин нэр.', NFC), when_service_id = null, when_launch_state = null, updated_at = now()
  from dt where k.tenant_id = dt.id and k.title = normalize('Таван AI ажилтан — нийтлэг', NFC);
